# Let me finally correctly apply the flood fill to the test input
# and prepare the submission

def flood_fill_3s_to_1s(input_grid):
    """Transform: 3s that are orthogonally adjacent (directly or indirectly) to a 2 become 1s"""
    rows = len(input_grid)
    cols = len(input_grid[0])
    result = [row[:] for row in input_grid]

    # Find all 2s as seeds
    seeds = set()
    for r in range(rows):
        for c in range(cols):
            if input_grid[r][c] == 2:
                seeds.add((r, c))

    # BFS to find all 3s that can reach a 2
    visited = set()
    queue = list(seeds)

    while queue:
        r, c = queue.pop(0)
        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited:
                    # 2s are seeds, so we don't process them further
                    # Only transform 3s
                    if input_grid[nr][nc] == 3:
                        visited.add((nr, nc))
                        result[nr][nc] = 1
                        queue.append((nr, nc))
                    # Continue to 2s through existing 3s, but don't recurse
                    elif input_grid[nr][nc] == 2:
                        visited.add((nr, nc))

    return result

