def transform_final(grid):
    """
    Final transformation:
    1. Fill 3s between 2s on both sides with 1s
    2. Fill 0s between 2s with 1s  
    3. Spread 1s to adjacent 0s and 3s (4-connected)
    """
    result = [list(row) for row in grid]

    for _ in range(3):  # Multiple passes for spreading
        changed = False
        # Pass 1: Fill 3s between 2s on both sides
        for r in range(len(result)):
            for c in range(len(result[r])):
                if result[r][c] == 3:
                    has_2_left = any(result[r][i] == 2 for i in range(c))
                    has_2_right = any(result[r][i] == 2 for i in range(c+1, len(result[r])))
                    if has_2_left and has_2_right:
                        result[r][c] = 1
                        changed = True

        # Pass 2: Fill 0s between 2s
        for r in range(len(result)):
            for c in range(len(result[r])):
                if result[r][c] == 0:
                    has_2_left = any(result[r][i] == 2 for i in range(c))
                    has_2_right = any(result[r][i] == 2 for i in range(c+1, len(result[r])))
                    if has_2_left and has_2_right:
                        result[r][c] = 1
                        changed = True

        # Pass 3: Spread to adjacent 0s and 3s
        for r in range(len(result)):
            for c in range(len(result[r])):
                if result[r][c] == 0 or result[r][c] == 3:
                    # Check if any neighbor is 1
                    neighbors = []
                    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                        nr, nc = r + dr, c + dc
                        if 0 <= nr < len(result) and 0 <= nc < len(result[r]):
                            neighbors.append(result[nr][nc])

                    if 1 in neighbors:
                        # Check bounding condition
                        has_2_left = any(result[r][i] == 2 for i in range(c))
                        has_2_right = any(result[r][i] == 2 for i in range(c+1, len(result[r])))
                        if has_2_left or has_2_right:
                            result[r][c] = 1
                            changed = True

        if not changed:
            break

    return result

